def find_first(seq, x):
    try:
        return seq.index(x)
    except ValueError:
        return -1

def find_last(seq, x):
    try:
        # Find all indices and take the max
        indices = [i for i, val in enumerate(seq) if val == x]
        return max(indices)
    except ValueError:
        return -1

